#!/usr/bin/env python3
"""
Guarded patch: replace the procedural Mining background with the actual
generated pickaxe-pattern image (real drawable resource, not runtime
Canvas math). Writes app/src/main/res/drawable/bg_mining_pickaxes.webp
and rewires miningThemedBackground() to paint it via ContentScale.Crop.
"""
import os
import base64

REPO_ROOT = "."
DRAWABLE_PATH = os.path.join(REPO_ROOT, "app/src/main/res/drawable/bg_mining_pickaxes.webp")
PATTERN_BG_PATH = os.path.join(REPO_ROOT, "app/src/main/kotlin/com/yourname/idlerpg/PatternBackground.kt")

IMAGE_B64 = """"""

# --- 1. Write the image drawable resource ---
os.makedirs(os.path.dirname(DRAWABLE_PATH), exist_ok=True)
image_bytes = base64.b64decode(IMAGE_B64)
if os.path.exists(DRAWABLE_PATH) and os.path.getsize(DRAWABLE_PATH) == len(image_bytes):
    print(f"SKIP (image already present, same size): {DRAWABLE_PATH}")
else:
    with open(DRAWABLE_PATH, "wb") as f:
        f.write(image_bytes)
    print(f"WROTE: {DRAWABLE_PATH} ({len(image_bytes)} bytes)")

# --- 2. Patch PatternBackground.kt ---
with open(PATTERN_BG_PATH, "r", encoding="utf-8") as f:
    content = f.read()


def guarded_replace(content, old, new, marker):
    if marker in content:
        print(f"SKIP (already applied): {marker[:50]}")
        return content
    count = content.count(old)
    if count != 1:
        raise RuntimeError(f"Expected exactly 1 match, found {count}.\n--- old_str ---\n{old}\n--- end ---")
    print(f"PATCHED: {marker[:50]}")
    return content.replace(old, new)


# 2a. New imports needed for image-based painting
old_imports = (
    "import androidx.compose.ui.graphics.drawscope.DrawScope\n"
    "import androidx.compose.ui.graphics.drawscope.Stroke\n"
    "import androidx.compose.ui.graphics.drawscope.rotate\n"
)
new_imports = (
    "import androidx.compose.runtime.Composable\n"
    "import androidx.compose.ui.draw.paint\n"
    "import androidx.compose.ui.graphics.drawscope.DrawScope\n"
    "import androidx.compose.ui.graphics.drawscope.Stroke\n"
    "import androidx.compose.ui.graphics.drawscope.rotate\n"
    "import androidx.compose.ui.layout.ContentScale\n"
    "import androidx.compose.ui.res.painterResource\n"
    "import com.yourname.idlerpg.R\n"
)
content = guarded_replace(
    content, old_imports, new_imports,
    marker="import androidx.compose.ui.res.painterResource",
)

# 2b. Replace the procedural miningThemedBackground() with the image-based version
old_fn = (
    "fun Modifier.miningThemedBackground(): Modifier = this.drawBehind {\n"
    "    val baseColor = skillThemeColor(\"MINING\") ?: MutedTeal\n"
    "    val gradient = Brush.verticalGradient(\n"
    "        colors = listOf(CharcoalBackground, baseColor.copy(alpha = GRADIENT_BOTTOM_ALPHA))\n"
    "    )\n"
    "    drawRect(brush = gradient)\n"
    "    drawMineSupportTrusses(baseColor.copy(alpha = 0.10f))\n"
    "    drawOreGlints(ParchmentGold.copy(alpha = 0.30f))\n"
    "    drawPickaxeSilhouette(\n"
    "        color = baseColor.copy(alpha = 0.16f),\n"
    "        center = Offset(size.width * 0.78f, size.height * 0.32f),\n"
    "        scale = 1.3f,\n"
    "        rotationDegrees = -35f\n"
    "    )\n"
    "}\n"
)
new_fn = (
    "// Real generated image asset (res/drawable/bg_mining_pickaxes.webp) - a\n"
    "// tessellated angled-pickaxe wallpaper pattern - painted to fill the\n"
    "// screen. Replaces the earlier procedural-Canvas attempt.\n"
    "@Composable\n"
    "fun Modifier.miningThemedBackground(): Modifier {\n"
    "    val painter = painterResource(id = R.drawable.bg_mining_pickaxes)\n"
    "    return this.paint(painter, contentScale = ContentScale.Crop)\n"
    "}\n"
)
content = guarded_replace(
    content, old_fn, new_fn,
    marker="// Real generated image asset (res/drawable/bg_mining_pickaxes.webp)",
)

# 2c. skillPatternBackground needs @Composable now that it conditionally
#     calls a @Composable function (miningThemedBackground)
old_dispatch = (
    "fun Modifier.skillPatternBackground(skillId: String): Modifier = when (skillId) {\n"
    "    \"MINING\" -> this.miningThemedBackground()\n"
    "    else -> this.proceduralThemeBackground(baseColor = skillThemeColor(skillId) ?: MutedTeal)\n"
    "}\n"
)
new_dispatch = (
    "@Composable\n"
    "fun Modifier.skillPatternBackground(skillId: String): Modifier = when (skillId) {\n"
    "    \"MINING\" -> this.miningThemedBackground()\n"
    "    else -> this.proceduralThemeBackground(baseColor = skillThemeColor(skillId) ?: MutedTeal)\n"
    "}\n"
)
content = guarded_replace(
    content, old_dispatch, new_dispatch,
    marker="@Composable\nfun Modifier.skillPatternBackground(skillId: String): Modifier = when (skillId) {",
)

with open(PATTERN_BG_PATH, "w", encoding="utf-8") as f:
    f.write(content)

print("\nDone.")
